<style>
.aim-chat-shell{max-width:1240px;margin:auto;padding:24px 30px 52px;color:var(--theme-header-text-color)}.aim-topbar,.aim-product,.aim-stage-heading,.aim-stage-footer,.aim-composer-label,.aim-options-toggle,.aim-composer footer{display:flex;align-items:center;justify-content:space-between;gap:16px}.aim-product{justify-content:flex-start}.aim-product-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:rgba(var(--theme-accent-rgb),.09);color:var(--theme-accent);font-size:18px}.aim-product strong{display:block;font-size:16px}.aim-product div span{display:block;font-size:11px;color:var(--theme-muted-text-color);margin-top:3px}.aim-library-link{display:flex;align-items:center;gap:8px;border:1px solid rgba(var(--theme-border-color-rgb),.65);border-radius:9px;padding:9px 12px;font-size:12px;color:var(--theme-muted-text-color)}.aim-library-link:hover{border-color:rgba(var(--theme-accent-rgb),.4);color:var(--theme-accent)}.aim-workspace{max-width:860px;margin:68px auto 0}.aim-workspace.has-result{max-width:1000px;margin-top:36px}.aim-welcome{text-align:center;margin-bottom:31px}.aim-welcome-icon{display:grid;place-items:center;width:58px;height:58px;margin:0 auto 18px;border-radius:19px;background:rgba(var(--theme-accent-rgb),.09);color:var(--theme-accent);font-size:27px}.aim-welcome>p,.aim-stage-heading>div>span,.aim-recent>div>span{font-size:10px;letter-spacing:.15em;font-weight:600;color:var(--theme-accent)}.aim-welcome h1{font-size:clamp(32px,4vw,48px);line-height:1.15;letter-spacing:-1.5px;font-weight:650;margin:12px 0}.aim-welcome h1 em{font-style:normal;color:var(--theme-accent)}.aim-welcome>span{font-size:14px;color:var(--theme-muted-text-color);line-height:1.7}.aim-composer{background:var(--theme-surface-base);border:1px solid rgba(var(--theme-border-color-rgb),.68);border-radius:22px;padding:21px 24px;box-shadow:0 12px 38px -28px rgba(var(--theme-accent-rgb),.32)}.aim-composer:focus-within{border-color:rgba(var(--theme-accent-rgb),.44);box-shadow:0 0 0 4px rgba(var(--theme-accent-rgb),.04),0 12px 38px -28px rgba(var(--theme-accent-rgb),.25)}.aim-composer-label{font-size:12px;color:var(--theme-muted-text-color);margin-bottom:14px}.aim-composer-label span{display:flex;gap:7px;align-items:center}.aim-composer-label span+span{font-size:10px}.aim-composer label{position:absolute!important;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.aim-composer textarea{border:0!important;background:transparent!important;box-shadow:none!important;padding:4px 0!important;min-height:125px;font-size:16px!important;line-height:1.8!important}.aim-options-toggle{width:100%;padding:13px 0;margin-top:8px;border-top:1px solid rgba(var(--theme-border-color-rgb),.6);font-size:12px;text-align:left}.aim-options-toggle span{display:flex;align-items:center;gap:8px}.aim-options-toggle span+span{font-size:11px;color:var(--theme-muted-text-color)}.aim-options{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:8px 0 20px}.aim-composer footer{padding-top:14px;border-top:1px solid rgba(var(--theme-border-color-rgb),.6)}.aim-credit{font-size:12px;color:var(--theme-muted-text-color)}.aim-credit i{color:var(--theme-accent);margin-right:6px}.aim-error{font-size:12px;color:var(--theme-danger-color);margin-top:8px}.aim-starters{margin-top:27px}.aim-starters>p{font-size:12px;color:var(--theme-muted-text-color);margin-bottom:11px}.aim-starters>div{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.aim-starters button,.aim-recent-grid button{position:relative;display:block;text-align:left;border:1px solid rgba(var(--theme-border-color-rgb),.64);border-radius:13px;padding:16px;background:color-mix(in srgb,var(--theme-surface-base) 75%,transparent);transition:.15s}.aim-starters button:hover,.aim-recent-grid button:hover{border-color:rgba(var(--theme-accent-rgb),.35);background:var(--theme-surface-base);transform:translateY(-2px)}.aim-starters button>i{position:absolute;right:14px;top:16px;color:var(--theme-muted-text-color);font-size:11px}.aim-starters strong,.aim-recent-grid strong{display:block;font-size:12px;font-weight:600}.aim-starters span,.aim-recent-grid span{display:block;margin-top:5px;font-size:11px;color:var(--theme-muted-text-color);line-height:1.6}.aim-stage{margin-bottom:32px}.aim-stage-heading{margin-bottom:17px}.aim-stage-heading h1{font-size:28px;font-weight:650;letter-spacing:-.8px;margin:7px 0 0}.aim-status{display:flex;align-items:center;gap:7px;border:1px solid rgba(var(--theme-accent-rgb),.25);border-radius:99px;padding:7px 10px;font-size:11px;color:var(--theme-accent);background:rgba(var(--theme-accent-rgb),.06)}.aim-image-stage{position:relative;display:flex;justify-content:center;min-height:360px;border-radius:21px;overflow:hidden;background:linear-gradient(135deg,rgba(var(--theme-accent-rgb),.1),rgba(var(--theme-accent-rgb),.025));border:1px solid rgba(var(--theme-border-color-rgb),.62)}.aim-image-stage img{display:block;max-height:660px;max-width:100%;opacity:0;transition:opacity .25s}.aim-image-stage img.is-ready{opacity:1}.aim-image-loading{position:absolute;inset:0;display:grid;place-content:center;text-align:center;color:var(--theme-muted-text-color);font-size:12px}.aim-image-loading i{font-size:25px;color:var(--theme-accent);margin-bottom:12px}.aim-stage-ratio{position:absolute;right:14px;top:14px;background:rgba(15,23,42,.6);color:white;padding:6px 9px;border-radius:8px;font-size:10px}.aim-stage-footer{padding:14px 0 0}.aim-stage-meta,.aim-stage-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.aim-stage-meta span{font-size:10px;color:var(--theme-muted-text-color);padding-right:8px;border-right:1px solid rgba(var(--theme-border-color-rgb),.6)}.aim-stage-meta span:last-child{border:0}.aim-recent{margin-top:42px}.aim-recent h2{font-size:22px;font-weight:650;letter-spacing:-.5px;margin:7px 0 17px}.aim-recent-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.aim-recent-grid button>i{display:block;color:var(--theme-accent);margin-bottom:12px}.aim-recent-grid button.is-active{border-color:rgba(var(--theme-accent-rgb),.4);background:rgba(var(--theme-accent-rgb),.05)}
@media(max-width:700px){.aim-chat-shell{padding:18px 16px 34px}.aim-workspace{margin-top:42px}.aim-workspace.has-result{margin-top:28px}.aim-welcome h1{font-size:34px}.aim-starters>div{grid-template-columns:1fr}.aim-options{grid-template-columns:1fr}.aim-stage-heading h1{font-size:23px}.aim-image-stage{min-height:300px}.aim-stage-footer{align-items:flex-start;flex-direction:column}.aim-recent-grid{grid-template-columns:repeat(2,1fr)}.aim-composer{padding:18px}.aim-library-link{padding:8px}.aim-library-link{font-size:0}.aim-library-link i{font-size:14px}}
</style>
